with flagged as (select *, case when lag(event_time) over (partition by session_id order by event_time asc, id asc) is null or event_time > lag(event_time) over (partition by session_id order by event_time asc, id asc) + interval '30' day then 1 else 0 end as is_new_burst from web_events), sessionized as (select *, sum(is_new_burst) over (partition by session_id order by event_time asc, id asc rows between unbounded preceding and current row) as burst_id from flagged) select case when duration_sec >= 384 then 'HIGH' else 'LOW' end as duration_sec_tier, (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 as duration_min, count(*) filter (where page = '/search') as search_rows, round(sum(duration_sec) / nullif(count(case when page = '/search' then 1 end), 0), 2) as duration_sec_per_search from sessionized group by case when duration_sec >= 384 then 'HIGH' else 'LOW' end order by duration_sec_per_search desc nulls first
